import {supabase,currentUser} from './auth-client.mjs';import {validateUid} from './player-model.mjs';
let dialog,form,input,status,save,checking=false,verifiedFor=null,promptFor=null;
function create(){if(dialog)return;dialog=document.createElement('dialog');dialog.className='required-uid-dialog';dialog.setAttribute('aria-label','Enter your In-Game ID (UID)');dialog.setAttribute('closedby','none');dialog.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();}});dialog.addEventListener('close',()=>{if(!verifiedFor)setTimeout(check,0);});dialog.addEventListener('cancel',e=>e.preventDefault());const title=document.createElement('h2');title.textContent='Enter your In-Game ID (UID)';const note=document.createElement('p');note.textContent='Your In-Game ID is locked after saving for now and will be used for all website features.';form=document.createElement('form');input=document.createElement('input');input.type='text';input.inputMode='numeric';input.autocomplete='off';input.required=true;input.maxLength=20;input.setAttribute('aria-label','In-Game ID (UID)');input.placeholder='In-Game ID';save=document.createElement('button');save.type='submit';save.textContent='Save UID';status=document.createElement('p');status.setAttribute('role','status');const retry=document.createElement('button');retry.type='button';retry.textContent='Retry verification';retry.onclick=check;form.append(input,save);dialog.append(title,note,form,status,retry);document.body.append(dialog);
 form.onsubmit=async e=>{e.preventDefault();save.disabled=true;try{const uid=validateUid(input.value),user=await currentUser();if(!user)throw Error('Please log in again.');const {data,error}=await supabase.rpc('claim_game_uid',{p_uid:uid,p_display_name:user.user_metadata?.full_name||user.user_metadata?.name||'Player'});if(error)throw error;if(data!==uid)throw Error('The UID save could not be confirmed. Please retry.');if((await currentUser())?.id!==user.id)throw Error('Your account changed. Please retry.');verifiedFor=user.id;dialog.close();window.dispatchEvent(new Event('game-uid-saved'));}catch(error){status.textContent=error.code==='PGRST202'?'UID setup is not available yet. Please contact the site owner.':error.message;}finally{save.disabled=false;}};
}
async function check(){if(checking||document.getElementById('callback-status'))return;checking=true;try{const user=await currentUser();if(!user){verifiedFor=null;if(dialog?.open)dialog.close();return;}if(verifiedFor===user.id)return;const {data,error}=await supabase.rpc('self_game_uid');if(error)throw error;if(data){validateUid(data);verifiedFor=user.id;if(dialog?.open)dialog.close();return;}create();if(promptFor!==user.id){input.value='';promptFor=user.id;}input.disabled=false;save.disabled=false;status.textContent='';if(!dialog.open)dialog.showModal();input.focus();}catch(error){create();input.disabled=true;save.disabled=true;status.textContent='We could not verify your UID. Retry, or contact the site owner.';if(!dialog.open)dialog.showModal();}finally{checking=false;}}
supabase.auth.onAuthStateChange((event,session)=>{if(!session)verifiedFor=null;setTimeout(check,0);});check();
